const cfg = $('Config').first().json;

function icon(hex) {
  return String.fromCodePoint(parseInt(hex, 16));
}

const I = {
  chart: icon('1F4CA'), money: icon('1F4B0'), target: icon('1F3AF'), rocket: icon('1F680'),
  card: icon('1F4B3'), cash: icon('1F4B8'), warning: String.fromCodePoint(0x26A0, 0xFE0F),
  red: icon('1F534'), yellow: icon('1F7E1'), green: icon('1F7E2'), fire: icon('1F525'),
  snow: icon('1F9CA'), clock: String.fromCodePoint(0x23F1, 0xFE0F), trophy: icon('1F3C6'),
  calendar: icon('1F4C5'), search: icon('1F50E'), pin: icon('1F4CC'), check: icon('2705'),
};

function safeNodeJson(name) {
  try {
    const all = $(name).all();
    if (all.length > 1) return all.map((item) => item.json);
    return all[0]?.json ?? {};
  } catch (error) {
    return {};
  }
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];
  if (Array.isArray(value.items)) return value.items;
  if (Array.isArray(value.data)) return value.data;
  if (Array.isArray(value.points)) return value.points;
  if (Array.isArray(value.alerts)) return value.alerts;
  if (Array.isArray(value.content)) return value.content;
  const keys = Object.keys(value);
  if (keys.length && keys.every((key) => /^\d+$/.test(key))) {
    return keys.sort((a, b) => Number(a) - Number(b)).map((key) => value[key]);
  }
  return [];
}

function toNumber(value) {
  const num = Number(value ?? 0);
  return Number.isFinite(num) ? num : 0;
}

function money(value) {
  return '$' + toNumber(value).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function percent(value) {
  return toNumber(value).toFixed(1) + '%';
}

function shortId(value) {
  return String(value || '').slice(0, 8) || 's/id';
}

function periodTotal(raw) {
  if (raw && typeof raw === 'object' && raw.totalAmount != null) return toNumber(raw.totalAmount);
  return asArray(raw?.points).reduce((sum, point) => sum + toNumber(point.total), 0);
}

function periodCount(raw) {
  if (raw && typeof raw === 'object' && raw.totalCount != null) return toNumber(raw.totalCount);
  return asArray(raw?.points).reduce((sum, point) => sum + toNumber(point.count), 0);
}

function isoDate(date) {
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
}

function dueDateForCurrentMonth(dueDay, baseDate) {
  if (!dueDay || dueDay < 1) return null;
  const lastDay = new Date(baseDate.getFullYear(), baseDate.getMonth() + 1, 0).getDate();
  return new Date(baseDate.getFullYear(), baseDate.getMonth(), Math.min(dueDay, lastDay));
}

function lines(items, formatter, emptyText, limit = 5) {
  const selected = items.slice(0, limit).map(formatter);
  return selected.length ? selected.join('\n') : emptyText;
}

function statusForRatio(ratio, expected) {
  if (ratio >= expected) return { icon: I.green, text: 'En ritmo' };
  if (ratio >= expected * 0.75) return { icon: I.yellow, text: 'Levemente bajo' };
  return { icon: I.red, text: 'Bajo el ritmo esperado' };
}

const dashboard = safeNodeJson('Get Dashboard Summary');
const dailySales = safeNodeJson('Get Daily Sales');
const monthlySales = safeNodeJson('Get Monthly Sales');
const targetsSummary = safeNodeJson('Get Targets Summary');
const targets = asArray(safeNodeJson('Get Targets Detail'));
const inventoryAlerts = asArray(safeNodeJson('Get Inventory Alerts'));
const arItems = asArray(safeNodeJson('Get Accounts Receivable'));
const expenses = asArray(safeNodeJson('Get Expenses')).filter((item) => item.active !== false);

const todayIso = cfg.todayDate || isoDate(new Date());
const now = new Date(todayIso + 'T00:00:00');
const currentHour = new Date().getHours();
const isTenCut = currentHour >= 10;
const reportTitle = isTenCut ? 'CORTE COMERCIAL 10:00' : 'REPORTE EJECUTIVO DIARIO';
const dayOfMonth = now.getDate();
const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
const expectedPercentToday = daysInMonth > 0 ? (dayOfMonth / daysInMonth) * 100 : 0;

const todaySalesAmount = periodTotal(dailySales) || toNumber(dashboard.todaySalesAmount);
const todaySalesCount = periodCount(dailySales) || toNumber(dashboard.todaySalesCount);
const monthSalesAmount = periodTotal(monthlySales) || toNumber(dashboard.monthSalesAmount);
const monthSalesCount = periodCount(monthlySales) || toNumber(dashboard.monthSalesCount);
const todayProfitAmount = toNumber(dashboard.todayProfitAmount);
const monthProfitAmount = toNumber(dashboard.monthProfitAmount);
const avgTicketToday = todaySalesCount > 0 ? todaySalesAmount / todaySalesCount : 0;
const avgTicketMonth = monthSalesCount > 0 ? monthSalesAmount / monthSalesCount : 0;
const projectedClose = dayOfMonth > 0 ? (monthSalesAmount / dayOfMonth) * daysInMonth : monthSalesAmount;

const totalTargets = toNumber(targetsSummary.totalTargets || targets.length);
const achievedTargets = toNumber(targetsSummary.achievedTargets || targets.filter((item) => item.targetAchieved).length);
const pendingTargets = toNumber(targetsSummary.pendingTargets || Math.max(totalTargets - achievedTargets, 0));
const totalMetaUnits = toNumber(targetsSummary.totalMetaUnits || targets.reduce((sum, item) => sum + toNumber(item.metaUnits), 0));
const totalTargetRevenue = toNumber(targetsSummary.totalTargetRevenue || targets.reduce((sum, item) => sum + toNumber(item.targetRevenue), 0));
const totalContribution = toNumber(targetsSummary.totalContribution || targets.reduce((sum, item) => sum + toNumber(item.contributionTotal), 0));
const totalFixedCost = toNumber(targetsSummary.totalFixedCost || targets.reduce((sum, item) => sum + toNumber(item.fixedCostApplied), 0));
const totalExpectedProfit = toNumber(targetsSummary.totalExpectedProfit || targets.reduce((sum, item) => sum + toNumber(item.expectedProfit), 0));
const unitsSold = targets.reduce((sum, item) => sum + toNumber(item.unitsSoldCurrent), 0);
const progressPercent = totalTargetRevenue > 0 ? (monthSalesAmount / totalTargetRevenue) * 100 : 0;
const unitProgressPercent = totalMetaUnits > 0 ? (unitsSold / totalMetaUnits) * 100 : 0;
const remainingToGoal = Math.max(totalTargetRevenue - monthSalesAmount, 0);
const requiredDailyAvg = daysInMonth > dayOfMonth ? remainingToGoal / (daysInMonth - dayOfMonth) : remainingToGoal;
const targetStatus = statusForRatio(progressPercent, expectedPercentToday);

const targetRows = targets.map((item) => {
  const metaUnits = toNumber(item.metaUnits);
  const sold = toNumber(item.unitsSoldCurrent);
  const missing = Math.max(metaUnits - sold, 0);
  const targetRevenue = toNumber(item.targetRevenue || toNumber(item.salePrice) * metaUnits);
  const progress = metaUnits > 0 ? (sold / metaUnits) * 100 : 0;
  return {
    name: item.softwareName || 'Producto',
    country: item.countryCode || '',
    type: item.customerType || '',
    metaUnits,
    sold,
    missing,
    price: toNumber(item.salePrice),
    targetRevenue,
    expectedProfit: toNumber(item.expectedProfit),
    deadline: item.deadline || 's/f',
    achieved: Boolean(item.targetAchieved),
    progress,
  };
});

const topProgress = targetRows.filter((item) => item.sold > 0).sort((a, b) => b.sold - a.sold);
const pushByRevenue = targetRows.filter((item) => !item.achieved).sort((a, b) => b.targetRevenue - a.targetRevenue);
const criticalTargets = targetRows
  .filter((item) => !item.achieved && item.progress < expectedPercentToday)
  .sort((a, b) => (a.progress - b.progress) || (b.targetRevenue - a.targetRevenue));

const coldProducts = inventoryAlerts.map((item) => item.name || item.softwareName || 'Producto');

const overdueAr = arItems.filter((item) => String(item.status || '').toUpperCase() === 'OVERDUE');
const openAr = arItems.filter((item) => ['OPEN', 'PARTIAL'].includes(String(item.status || '').toUpperCase()));
const overdueArTotal = overdueAr.reduce((sum, item) => sum + toNumber(item.balance), 0);
const openArTotal = openAr.reduce((sum, item) => sum + toNumber(item.balance), 0);

const next3Date = new Date(now);
next3Date.setDate(next3Date.getDate() + 3);
const next3Iso = isoDate(next3Date);
const expenseSchedule = expenses
  .map((item) => {
    const dueDate = dueDateForCurrentMonth(toNumber(item.dueDay), now);
    return {
      name: (item.name || 'Gasto').trim(),
      category: item.category || '',
      amount: toNumber(item.monthlyAmount ?? item.totalAmount),
      dueDay: toNumber(item.dueDay),
      priority: item.priority || '',
      dueDateIso: dueDate ? isoDate(dueDate) : null,
    };
  })
  .filter((item) => item.dueDateIso);

const dueTodayExpenses = expenseSchedule.filter((item) => item.dueDateIso === todayIso);
const overdueExpenses = expenseSchedule.filter((item) => item.dueDateIso < todayIso);
const nextExpenses = expenseSchedule.filter((item) => item.dueDateIso > todayIso && item.dueDateIso <= next3Iso);
const dueTodayExpensesTotal = dueTodayExpenses.reduce((sum, item) => sum + item.amount, 0);
const overdueExpensesTotal = overdueExpenses.reduce((sum, item) => sum + item.amount, 0);
const nextExpensesTotal = nextExpenses.reduce((sum, item) => sum + item.amount, 0);

let globalIcon = I.green;
let globalStatus = 'Operaci�n estable';
const alerts = [];
if (overdueArTotal > 0) alerts.push(`${I.red} Cartera vencida: ${money(overdueArTotal)}`);
if (overdueExpensesTotal > 0) alerts.push(`${I.red} Gastos vencidos: ${money(overdueExpensesTotal)}`);
if (targetStatus.icon !== I.green) alerts.push(`${targetStatus.icon} Meta mensual: ${targetStatus.text}`);
if (todaySalesAmount <= 0) alerts.push(`${I.yellow} Sin ventas registradas hoy`);
if (alerts.some((item) => item.startsWith(I.red))) {
  globalIcon = I.red;
  globalStatus = 'Atenci�n financiera';
} else if (alerts.length > 0) {
  globalIcon = I.yellow;
  globalStatus = 'Seguimiento requerido';
}

const actionPlan = [];
if (overdueArTotal > 0) actionPlan.push('Cobrar cartera vencida antes de nuevas compras fuertes.');
if (overdueExpensesTotal > 0) actionPlan.push('Regularizar gastos vencidos o priorizar caja.');
if (remainingToGoal > 0) actionPlan.push(`Para cerrar meta, vender aprox. ${money(requiredDailyAvg)} diarios el resto del mes.`);
if (criticalTargets.length > 0) actionPlan.push(`Empujar primero: ${criticalTargets[0].name}.`);
if (actionPlan.length === 0) actionPlan.push('Mantener ritmo comercial y seguimiento de metas abiertas.');

const summaryBlock =
`${I.chart} <b>${reportTitle}</b>\n` +
`${I.calendar} Fecha: <b>${todayIso}</b>\n` +
`Estado: <b>${globalIcon} ${globalStatus}</b>\n` +
`Ritmo meta: <b>${targetStatus.icon} ${targetStatus.text}</b>\n`;

const salesBlock =
`${I.money} <b>VENTAS</b>\n` +
`Hoy: <b>${money(todaySalesAmount)}</b> (${todaySalesCount} ventas)\n` +
`Ticket prom. hoy: <b>${money(avgTicketToday)}</b>\n` +
`Mes: <b>${money(monthSalesAmount)}</b> (${monthSalesCount} ventas)\n` +
`Ticket prom. mes: <b>${money(avgTicketMonth)}</b>\n` +
`Utilidad hoy: <b>${money(todayProfitAmount)}</b>\n` +
`Utilidad mes: <b>${money(monthProfitAmount)}</b>\n` +
`Proyecci�n cierre: <b>${money(projectedClose)}</b>\n`;

const targetsBlock =
`${I.target} <b>METAS ACTIVAS</b>\n` +
`Meta ingresos: <b>${money(totalTargetRevenue)}</b>\n` +
`Vendido vs meta: <b>${money(monthSalesAmount)}</b> / <b>${money(totalTargetRevenue)}</b>\n` +
`Avance ingresos: <b>${percent(progressPercent)}</b> | esperado: <b>${percent(expectedPercentToday)}</b>\n` +
`Faltante: <b>${money(remainingToGoal)}</b>\n` +
`Necesario diario: <b>${money(requiredDailyAvg)}</b>\n` +
`Unidades: <b>${unitsSold}/${totalMetaUnits}</b> (${percent(unitProgressPercent)})\n` +
`Metas logradas: <b>${achievedTargets}/${totalTargets}</b> | pendientes: <b>${pendingTargets}</b>\n` +
`Contribuci�n: <b>${money(totalContribution)}</b>\n` +
`Costos fijos: <b>${money(totalFixedCost)}</b>\n` +
`Utilidad esperada: <b>${money(totalExpectedProfit)}</b>\n`;

const progressLines = lines(topProgress, (item, index) =>
  `${index + 1}. ${item.name}: ${item.sold}/${item.metaUnits} und. (${percent(item.progress)})`,
  'Sin productos con avance registrado'
);
const criticalLines = lines(criticalTargets, (item, index) =>
  `${index + 1}. ${item.name}: faltan ${item.missing} und. | ${percent(item.progress)} | vence ${item.deadline}`,
  'Sin metas cr�ticas por debajo del ritmo'
);
const pushLines = lines(pushByRevenue, (item, index) =>
  `${index + 1}. ${item.name}: meta ${money(item.targetRevenue)} | faltan ${item.missing} und. | precio ${money(item.price)}`,
  'Sin metas pendientes'
);
const coldLines = lines(coldProducts, (name) => `- ${name}`, 'Sin productos fr�os');
const alertLines = alerts.length ? alerts.join('\n') : `${I.check} Sin alertas cr�ticas`;
const actionLines = actionPlan.map((item, index) => `${index + 1}. ${item}`).join('\n');

const arLines = lines(overdueAr, (item) =>
  `- Venta ${shortId(item.saleId)}: ${money(item.balance)} | vence ${item.dueDate || 's/f'}`,
  'Sin cartera vencida'
);
const expensesTodayLines = lines(dueTodayExpenses, (item) => `- ${item.name}: ${money(item.amount)}`, 'Sin pagos hoy');
const expensesOverdueLines = lines(overdueExpenses, (item) => `- ${item.name}: ${money(item.amount)} | d�a ${item.dueDay}`, 'Sin gastos vencidos');
const expensesNextLines = lines(nextExpenses, (item) => `- ${item.name}: ${money(item.amount)} | ${item.dueDateIso}`, 'Sin pagos pr�ximos');

const message =
`${summaryBlock}\n` +
`${salesBlock}\n` +
`${targetsBlock}\n` +
`${I.trophy} <b>TOP AVANCE</b>\n${progressLines}\n\n` +
`${I.warning} <b>METAS CR�TICAS</b>\n${criticalLines}\n\n` +
`${I.rocket} <b>METAS A EMPUJAR POR INGRESO</b>\n${pushLines}\n\n` +
`${I.snow} <b>PRODUCTOS FR�OS</b>\n${coldLines}\n\n` +
`${I.card} <b>CARTERA</b>\n` +
`Vencida: <b>${money(overdueArTotal)}</b> (${overdueAr.length})\n` +
`Abierta: <b>${money(openArTotal)}</b> (${openAr.length})\n` +
`${arLines}\n\n` +
`${I.cash} <b>GASTOS</b>\n` +
`Hoy: <b>${money(dueTodayExpensesTotal)}</b>\n${expensesTodayLines}\n\n` +
`Vencidos: <b>${money(overdueExpensesTotal)}</b>\n${expensesOverdueLines}\n\n` +
`Pr�ximos 3 d�as: <b>${money(nextExpensesTotal)}</b>\n${expensesNextLines}\n\n` +
`${I.search} <b>ALERTAS</b>\n${alertLines}\n\n` +
`${I.pin} <b>PLAN DE ACCI�N</b>\n${actionLines}`;

return [{
  json: {
    message,
    globalStatus,
    todaySalesAmount,
    monthSalesAmount,
    totalTargetRevenue,
    progressPercent,
    expectedPercentToday,
    remainingToGoal,
    requiredDailyAvg,
    unitsSold,
    totalMetaUnits,
    overdueArTotal,
    overdueExpensesTotal,
    nextExpensesTotal,
  }
}];
